<?php
defined('ABSPATH') || exit;
final class MNIN_Quality_Reception {
    public static function criteria(){return array('originals'=>'Illustrations, logo et polices conformes aux originaux approuvés','geometry'=>'Composition conforme au viewport de référence','responsive'=>'Ordinateur, tablette et mobile contrôlés','interactions'=>'Boutons, menus et formulaires fonctionnels','goal'=>'Objectif enregistré et retrouvé par son élève','progress'=>'Progression reliée aux activités réelles','quality'=>'Performance, sécurité et accessibilité vérifiées','restore'=>'Restauration de la version précédente testée');}
    public static function fingerprint($id){$p=get_post($id);if(!$p)return '';$files=array();$paths=array(get_stylesheet_directory().'/functions.php');if(defined('MNIN_PIXEL_DIR'))foreach(array('includes/class-mnin-pixel-studio.php','templates/objectifs.php','templates/content.php','assets/css/objectifs.css') as $file)$paths[]=MNIN_PIXEL_DIR.$file;foreach($paths as $path)if(is_file($path))$files[$path]=hash_file('sha256',$path);return hash('sha256',wp_json_encode(array(MNIN_Progress_Quality::page_hash($p),get_option('mnin_design_reference'),get_option('mnin_design_tokens'),get_option('mnin_pixel_studio_options'),get_stylesheet(),$files,defined('MNIN_PIXEL_VERSION')?MNIN_PIXEL_VERSION:'absent',MNIN_Progress_Quality::VERSION)));}
    public static function ready($id){$r=get_post_meta($id,'_mnin_quality_reception',true);$reference=get_option('mnin_design_reference',array());if(empty($reference['locked'])||!isset($reference['page_id'])||(int)$reference['page_id']!==(int)$id||!is_array($r)||empty($r['fingerprint'])||!hash_equals(self::fingerprint($id),$r['fingerprint']))return false;foreach(self::criteria() as $key=>$label)if(empty($r['checks'][$key])||empty($r['evidence'][$key]))return false;return true;}
    public static function action(){
        if(!current_user_can('manage_options'))wp_die('Accès refusé.');check_admin_referer('mnin_quality_reception');$id=isset($_POST['page_id'])?absint($_POST['page_id']):0;$p=get_post($id);if(!$p||'page'!==$p->post_type||!current_user_can('edit_post',$id))wp_die('Page invalide.');
        $expected=isset($_POST['fingerprint'])?sanitize_text_field(wp_unslash($_POST['fingerprint'])):'';if(!hash_equals(self::fingerprint($id),$expected))wp_die('La page ou sa configuration a changé. Rechargez la réception avant de poursuivre.');
        if(isset($_POST['publish'])){if(!self::ready($id))wp_die('Publication refusée : les huit critères documentés et la référence verrouillée doivent correspondre à cette version.');if('publish'!==$p->post_status)MNIN_Progress_Quality::capture($id);$result=wp_update_post(array('ID'=>$id,'post_status'=>'publish'),true);if(is_wp_error($result))wp_die(esc_html($result->get_error_message()));
        }else{$checks=array();$evidence=array();foreach(self::criteria() as $key=>$label){$proof=isset($_POST['evidence'][$key])&&is_string($_POST['evidence'][$key])?wp_html_excerpt(sanitize_textarea_field(wp_unslash($_POST['evidence'][$key])),1200):'';$checks[$key]=!empty($_POST['checks'][$key])&&strlen($proof)>=10;$evidence[$key]=$proof;}update_post_meta($id,'_mnin_quality_reception',array('checks'=>$checks,'evidence'=>$evidence,'fingerprint'=>self::fingerprint($id),'date'=>gmdate('c'),'reviewer'=>get_current_user_id()));}
        wp_safe_redirect(add_query_arg(array('page'=>'mnin-reception','page_id'=>$id),admin_url('admin.php')));exit;
    }
    public static function panel(){
        if(!current_user_can('manage_options'))return;$id=isset($_GET['page_id'])?absint($_GET['page_id']):344;$p=get_post($id);$r=get_post_meta($id,'_mnin_quality_reception',true);$r=is_array($r)?$r:array();$fresh=isset($r['fingerprint'])&&hash_equals(self::fingerprint($id),$r['fingerprint']);$count=0;foreach(self::criteria() as $key=>$v)if($fresh&&!empty($r['checks'][$key]))$count++;
        echo '<div class="wrap"><h1>MNIN — Réception avant publication</h1><p>Les cases sont des validations documentées par un administrateur, pas un audit automatique. Ce circuit contrôle la publication effectuée depuis ce panneau ; il ne remplace pas les autres permissions WordPress.</p><form method="get"><input type="hidden" name="page" value="mnin-reception"><label>Page <input type="number" min="1" name="page_id" value="'.esc_attr($id).'"></label> <button class="button">Charger</button></form>';
        if(!$p||'page'!==$p->post_type){echo '<p>Page introuvable.</p></div>';return;}
        echo '<h2>'.esc_html($p->post_title).' — '.(int)$count.'/8 contrôles documentés</h2><p>État WordPress : '.esc_html($p->post_status).'. '.($fresh?'Réception correspondant à la version courante.':'Aucune réception courante : à compléter après les tests réels.').'</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('mnin_quality_reception');echo '<input type="hidden" name="action" value="mnin_quality_reception"><input type="hidden" name="page_id" value="'.esc_attr($id).'"><input type="hidden" name="fingerprint" value="'.esc_attr(self::fingerprint($id)).'"><table class="widefat striped"><thead><tr><th>Critère</th><th>Preuves et résultat (minimum 10 caractères)</th></tr></thead><tbody>';
        foreach(self::criteria() as $key=>$label)echo '<tr><td><label><input type="checkbox" name="checks['.esc_attr($key).']" value="1" '.checked($fresh&&!empty($r['checks'][$key]),true,false).'> '.esc_html($label).'</label></td><td><textarea rows="3" class="widefat" name="evidence['.esc_attr($key).']">'.esc_textarea(isset($r['evidence'][$key])?$r['evidence'][$key]:'').'</textarea></td></tr>';
        echo '</tbody></table><p><button class="button button-primary">Enregistrer les preuves de réception</button></p></form><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('mnin_quality_reception');echo '<input type="hidden" name="action" value="mnin_quality_reception"><input type="hidden" name="page_id" value="'.esc_attr($id).'"><input type="hidden" name="fingerprint" value="'.esc_attr(self::fingerprint($id)).'"><button class="button" name="publish" value="1" '.disabled(self::ready($id),false,false).'>Publier cette version validée</button></form><p>Une modification du contenu, du thème actif, des réglages Pixel Studio, des tokens ou de la référence invalide la réception. Les changements de fichiers externes nécessitent un nouveau contrôle manuel.</p></div>';
    }
}
add_action('admin_menu',function(){add_submenu_page('mnin-quality','Réception avant publication','Réception des pages','manage_options','mnin-reception',array('MNIN_Quality_Reception','panel'));});
add_action('admin_post_mnin_quality_reception',array('MNIN_Quality_Reception','action'));

